import type { Availability, ProductDetails, ProductReview } from "@/core";
import {
  isAvailability,
  optionalString,
  requireArray,
  requireNumber,
  requireRecord,
  requireString,
  requireStringArray,
} from "@/core";

// product-details.json is generated by `yarn catalog:build`, like catalog.json, and is
// validated on load for the same reason.
export function parseProductDetailsFile(json: unknown): ProductDetails[] {
  return requireArray(json, "product-details.json").map((item, index) =>
    parseDetails(item, `product-details.json[${index}]`),
  );
}

function parseDetails(value: unknown, context: string): ProductDetails {
  const record = requireRecord(value, context);
  return {
    productId: requireString(record, "productId", context),
    description: requireString(record, "description", context),
    images: requireStringArray(record, "images", context),
    availability: readAvailability(optionalString(record, "availability", context), context),
    shipping: optionalString(record, "shipping", context),
    warranty: optionalString(record, "warranty", context),
    returnPolicy: optionalString(record, "returnPolicy", context),
    reviews: requireArray(record.reviews, `${context} reviews`).map((review, reviewIndex) =>
      parseReview(review, `${context} review ${reviewIndex}`),
    ),
  };
}

function readAvailability(value: string | null, context: string): Availability | null {
  if (value === null) return null;
  if (!isAvailability(value)) throw new Error(`${context}: unknown availability "${value}"`);
  return value;
}

function parseReview(value: unknown, context: string): ProductReview {
  const record = requireRecord(value, context);
  return {
    reviewerName: requireString(record, "reviewerName", context),
    rating: requireNumber(record, "rating", context),
    comment: requireString(record, "comment", context),
    date: requireString(record, "date", context),
  };
}
